"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["43334"],{48875(e){e.exports=JSON.parse('{"id":"FIN-286","slug":"public-company","term":"Public Company","also_known_as":[],"difficulty":"Intermediate","definition":"A public company is a company whose shares can be bought and sold by members of the public, usually on a stock exchange.","explanation":["A company becomes public, usually through an initial public offering, when it sells shares to outside investors and lists them on an exchange. After that, anyone with a brokerage account can buy its shares.","Being public has advantages. The company can raise large amounts of money by issuing shares or bonds, its shares can be used to pay for acquisitions or reward employees, and shareholders can easily sell their stakes. It also often raises the company\'s profile.","There are significant responsibilities. Public companies must publish audited financial statements and other important information regularly, follow strict rules on disclosure and governance and respond to shareholders, who can vote on major issues. They face pressure from investors and analysts to deliver results every quarter.","For example, a public company must announce material news, such as a large contract loss, promptly so that all investors have access to the same information.","In some countries, \\"public company\\" can also mean a company eligible to offer shares to the public even if they are not listed. The term should not be confused with a government-owned company."],"note":"","total":1500,"prev":{"slug":"proxy-voting","term":"Proxy Voting"},"next":{"slug":"public-good","term":"Public Good"}}')}}]);